import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	n, _ := readInt(reader)
	sum := int64(0)
	p := int64(1)
	for n > 0 {
		p *= 2
		sum += p
		n--
	}
	fmt.Println(sum)
}

func readInt(reader *bufio.Reader) (int, error) {
	input, err := reader.ReadString('\n')
	if err != nil {
		return 0, err
	}
	input = input[:len(input)-1]
	var num int
	_, err = fmt.Sscanf(input, "%d", &num)
	return num, err
}
